SELECT DATE_TRUNC('MONTH', p.launch_date) AS launch_month, CASE WHEN p.cost >= 800 THEN 'high' WHEN p.cost >= 320 THEN 'mid' ELSE 'low' END AS cost_bucket, COUNT(*) AS row_count, COUNT(DISTINCT i.quantity) AS unique_products FROM inventory i INNER JOIN stores s ON i.store_id = s.id LEFT OUTER JOIN products p ON i.product_id = p.id GROUP BY DATE_TRUNC('MONTH', p.launch_date), CASE WHEN p.cost >= 800 THEN 'high' WHEN p.cost >= 320 THEN 'mid' ELSE 'low' END;
